def run_bst(root, values):
    def add(node, key):
        if node is None:
            return TreeNode(key), True
        if key == node.val:
            return node, False
        if key < node.val:
            node.left, added = add(node.left, key)
        else:
            node.right, added = add(node.right, key)
        return node, added
    added = 0
    for key in values[::-1]:
        root, changed = add(root, key)
        added += int(changed)
    return (root, added)

